import { SESSION_ID_COOKIE_NAME } from "#app/constants";
import { globalScene } from "#app/global-scene";
import { getCookie } from "#utils/cookies";

async function api(path: string, body?: unknown): Promise<any> {
  const base = import.meta.env.VITE_SERVER_URL;
  if (!base) throw new Error("Account server is not configured.");
  const response = await fetch(`${base}${path}`, {
    method: body === undefined ? "GET" : "POST",
    headers: { Authorization: getCookie(SESSION_ID_COOKIE_NAME), "Content-Type": "application/json" },
    body: body === undefined ? null : JSON.stringify(body),
  });
  const raw = await response.text();
  let data: any;
  try { data = JSON.parse(raw); } catch { data = { error: raw }; }
  if (!response.ok) throw new Error(data.error || `Request failed (${response.status})`);
  return data;
}

function node<K extends keyof HTMLElementTagNameMap>(tag: K, text = ""): HTMLElementTagNameMap[K] {
  const element = document.createElement(tag);
  element.textContent = text;
  return element;
}

let closeActivePanel: (() => void) | null = null;
function panel(title: string) {
  closeActivePanel?.();
  const overlay = node("section");
  overlay.id = "live-ops-panel";
  overlay.setAttribute("role", "dialog");
  overlay.setAttribute("aria-modal", "true");
  overlay.setAttribute("aria-label", title);
  overlay.style.cssText = "position:fixed;inset:3%;z-index:10000;overflow:auto;background:#303447;color:#fff;border:6px solid #b6312a;border-radius:12px;padding:20px;font:16px system-ui;box-shadow:0 0 0 100vmax #000b;";
  const heading = node("h1", title);
  const close = node("button", "Back to game");
  const keyboard = globalScene?.input?.keyboard;
  const keyboardEnabled = keyboard?.enabled;
  if (keyboard) keyboard.enabled = false;
  closeActivePanel = () => { overlay.remove(); if (keyboard) keyboard.enabled = keyboardEnabled ?? true; closeActivePanel = null; };
  close.onclick = () => closeActivePanel?.();
  overlay.append(heading, close);
  const content = node("div");
  overlay.append(content);
  const style = node("style");
  style.textContent = "#live-ops-panel button{padding:9px 14px;margin:6px;border:2px solid #e9e9ee;border-radius:5px;background:#484d66;color:white;cursor:pointer}#live-ops-panel button:disabled{opacity:.5;cursor:wait}#live-ops-panel label{display:block;margin:12px 0}#live-ops-panel input,#live-ops-panel textarea,#live-ops-panel select{display:block;width:min(95%,800px);padding:8px;background:#171c2b;color:#fff;border:1px solid #aab0c6}#live-ops-panel article{border:1px solid #777e99;padding:12px;margin:12px 0}#live-ops-panel pre{white-space:pre-wrap;overflow-wrap:anywhere}";
  overlay.append(style);
  document.body.append(overlay);
  close.focus();
  return content;
}

function error(container: HTMLElement, reason: unknown) {
  const message = node("p", reason instanceof Error ? reason.message : String(reason));
  message.setAttribute("role", "alert");
  container.append(message);
}

export function showRoomClosed(reason: string) {
  const content = panel("Online room closed");
  content.append(node("p", reason), node("p", "The online connection has ended. No recovery or reward changes were applied."));
}

export function showMultiplayerRestriction(restriction: any) {
  const content = panel("Multiplayer access restricted");
  content.append(node("p", `Scope: ${restriction?.scope ?? "multiplayer"}`), node("p", String(restriction?.reason ?? "Contact the server owner.")), node("p", `Expires: ${new Date(restriction?.expires_at).toLocaleString()}`));
}

export async function showLiveEvents() {
  const content = panel("Live Events");
  content.textContent = "Loading events…";
  try {
    const data = await api("/live/events");
    content.replaceChildren();
    if (!data.events.length) content.append(node("p", "No active or upcoming events."));
    try {
      const account = await api("/account/info");
      if (account.accountId) content.append(node("p", `Your verified account ID: ${account.accountId}`));
    } catch { /* Public event listings also work without a login. */ }
    for (const event of data.events) {
      const card = node("article");
      card.append(node("h2", event.name), node("p", event.description), node("p", `${event.status} • ${event.formats.join(", ")}`), node("p", `Entries close: ${new Date(event.endsAt).toLocaleString()}`));
      content.append(card);
    }
  } catch (reason) { content.replaceChildren(); error(content, reason); }
}

type Resource = "events" | "announcements";
function field(form: HTMLElement, name: string, value: string, type = "text") {
  const label = node("label", name);
  const input = type === "textarea" ? node("textarea") : node("input");
  if (input instanceof HTMLInputElement) input.type = type;
  input.value = value;
  label.append(input);
  form.append(label);
  return input;
}
function localTime(iso: string) {
  const date = new Date(iso);
  return new Date(date.getTime() - date.getTimezoneOffset() * 60000).toISOString().slice(0, 16);
}

export async function showAdminPanel() {
  const content = panel("Admin Panel — NamoYT");
  content.textContent = "Verifying account…";
  try { await api("/admin/access"); }
  catch (reason) { content.replaceChildren(); error(content, reason); return; }
  content.replaceChildren();
  const navigation = node("nav");
  const view = node("div");
  content.append(navigation, view);
  const open = async (section: string) => {
    view.textContent = "Loading…";
    try {
      if (section === "Dashboard") {
        const data = await api("/admin/live/dashboard");
        const events = await api("/admin/live/events");
        view.replaceChildren(node("h2", "Dashboard"), node("p", `Online players: ${data.onlinePlayers}`), node("p", data.roomsStatus));
        view.append(node("p", `Events: ${events.events.length}; live: ${events.events.filter((e: any) => e.status === "live").length}; scheduled: ${events.events.filter((e: any) => e.status === "scheduled").length}`));
        view.append(node("h3", "Recent activity"), node("pre", JSON.stringify(data.activity, null, 2)), node("h3", "Recent failed operations"), node("pre", JSON.stringify(data.failures, null, 2)));
      } else if (section === "Audit Log") {
        const data = await api("/admin/live/audit");
        view.replaceChildren(node("h2", "Read-only audit log"), node("pre", data.entries.length ? JSON.stringify(data.entries, null, 2) : "No operations recorded."));
      } else if (section === "Live Events" || section === "Announcements") {
        await list(section === "Live Events" ? "events" : "announcements");
      } else if (section === "Rooms & Runs") {
        view.replaceChildren(node("h2", "Rooms & Runs"));
        const search = field(view, "Room code, run ID or player", "");
        const find = node("button", "Search");
        const results = node("div");
        view.append(find, results);
        const load = async () => {
          find.disabled = true; results.textContent = "Loading rooms…";
          try {
            const data = await api(`/admin/live/rooms?q=${encodeURIComponent(search.value)}`);
            results.replaceChildren(node("p", `Active rooms: ${data.activeCount}`));
            if (!data.rooms.length) results.append(node("p", "No matching rooms."));
            for (const room of data.rooms) {
              const card = node("article");
              card.append(node("h3", `${room.joinCode} — ${room.lifecycleState}`), node("pre", JSON.stringify(room, null, 2)));
              const reason = field(card, "Reason for closing this room", "");
              const close = node("button", "Close room");
              close.disabled = room.lifecycleState === "abandoned";
              let operationId = crypto.randomUUID();
              reason.oninput = () => { operationId = crypto.randomUUID(); };
              close.onclick = async () => {
                if (reason.value.trim().length < 3) { error(card, "A reason is required."); return; }
                if (!window.confirm("Close this online room and notify its players? This does not restore a checkpoint or issue rewards.")) return;
                close.disabled = true; reason.disabled = true;
                try {
                  await api("/admin/live/rooms/close", { roomId: room.roomId, reason: reason.value.trim(), confirmed: true, operationId });
                  card.append(node("p", "Room closed. Players notified."));
                } catch (failure) { error(card, failure); close.disabled = false; reason.disabled = false; }
              };
              card.append(close, node("p", "Checkpoint recovery is unavailable until authoritative checkpoint storage is integrated."));
              results.append(card);
            }
          } catch (failure) { results.replaceChildren(); error(results, failure); }
          finally { find.disabled = false; }
        };
        find.onclick = () => { void load(); };
        await load();
      } else if (section === "Players & Rewards") {
        const data = await api("/admin/users");
        view.replaceChildren(node("h2", "Players"), node("p", "Reward grants are unavailable until server-verified event completion is integrated."));
        const search = field(view, "Search username or account ID", "");
        const results = node("div");
        const details = node("div");
        const inspect = async (accountId: number) => {
          details.textContent = "Loading player…";
          try {
            const player = await api(`/admin/live/player?accountId=${accountId}`);
            details.replaceChildren(node("h3", `${player.user.username} — account ${player.user.id}`), node("h4", "Event entries and reward grants"), node("pre", JSON.stringify({ entries: player.entries, claims: player.claims }, null, 2)));
            const form = node("form");
            const reason = field(form, "Multiplayer restriction reason", "");
            const expiry = field(form, "Expires (local time, maximum 30 days)", localTime(new Date(Date.now() + 3600000).toISOString()), "datetime-local");
            const apply = node("button", "Apply restriction"); apply.type = "submit";
            const status = node("p"); status.setAttribute("role", "status");
            form.append(apply, status); details.append(form);
            let payload: any;
            form.oninput = () => { payload = null; };
            form.onsubmit = async event => {
              event.preventDefault();
              if (apply.disabled || !window.confirm(`Restrict multiplayer access for account ${accountId}?`)) return;
              apply.disabled = true; reason.disabled = true; expiry.disabled = true;
              status.textContent = "Saving…";
              try {
                payload ??= { accountId, operationId: crypto.randomUUID(), reason: reason.value, expiresAt: new Date(expiry.value).toISOString() };
                await api("/admin/live/restrictions/apply", payload);
                await inspect(accountId);
              } catch (failure) { status.textContent = failure instanceof Error ? failure.message : String(failure); }
              finally { apply.disabled = false; reason.disabled = false; expiry.disabled = false; }
            };
            details.append(node("h4", "Restriction history"));
            if (!player.restrictions.length) details.append(node("p", "No restrictions."));
            for (const restriction of player.restrictions) {
              const card = node("article");
              const active = !restriction.removed_at && restriction.expires_at > Date.now();
              card.append(node("p", `${active ? "Active" : "Inactive"} • ${restriction.scope} • expires ${new Date(restriction.expires_at).toLocaleString()}`), node("p", restriction.reason));
              if (active) {
                const remove = node("button", "Remove restriction");
                let removal: any;
                remove.onclick = async () => {
                  if (remove.disabled) return;
                  if (!removal) {
                    const explanation = window.prompt("Reason for removing this restriction:");
                    if (!explanation?.trim()) return;
                    removal = { accountId, restrictionId: restriction.id, operationId: crypto.randomUUID(), reason: explanation.trim() };
                  }
                  remove.disabled = true;
                  try { await api("/admin/live/restrictions/remove", removal); await inspect(accountId); }
                  catch (failure) { error(card, failure); remove.disabled = false; }
                };
                card.append(remove);
              }
              details.append(card);
            }
          } catch (failure) { details.replaceChildren(); error(details, failure); }
        };
        const render = () => {
          results.replaceChildren();
          const matches = data.users.filter((u: any) => String(u.id) === search.value || u.username.toLowerCase().includes(search.value.toLowerCase()));
          if (!matches.length) results.append(node("p", "No matching players in the recent account list."));
          for (const user of matches) {
            const button = node("button", `${user.username} (#${user.id})`);
            button.onclick = () => { void inspect(user.id); }; results.append(button);
          }
        };
        search.oninput = render;
        view.append(results, details); render();
      } else {
        view.replaceChildren(node("h2", section), node("p", "Not connected yet. No recovery, reward or encounter changes can be made from this section."));
      }
    } catch (reason) { view.replaceChildren(); error(view, reason); }
  };
  const edit = (resource: Resource, record: any) => {
    view.replaceChildren(node("h2", resource === "events" ? "Event draft editor" : "Announcement editor"));
    const original = record.document;
    const form = node("form");
    const name = field(form, resource === "events" ? "Event name" : "Title", resource === "events" ? original.name : original.title);
    const description = field(form, resource === "events" ? "Description" : "Message", resource === "events" ? original.description : original.message, "textarea");
    const start = field(form, "Starts (your local timezone)", localTime(original.startsAt), "datetime-local");
    const end = field(form, "Ends (your local timezone)", localTime(original.endsAt), "datetime-local");
    const states = node("select");
    for (const value of resource === "events" ? ["draft", "ended", "cancelled"] : ["draft", "published", "archived"]) {
      const option = node("option", value); option.value = value; states.append(option);
    }
    states.value = original.state;
    const stateLabel = node("label", "State"); stateLabel.append(states); form.append(stateLabel);
    const rules = resource === "events" ? field(form, "Eligibility and rules (JSON; draft only)", JSON.stringify({ modes: original.modes, formats: original.formats, rules: original.rules }, null, 2), "textarea") : null;
    const kind = node("select");
    for (const value of ["banner", "event", "maintenance"]) { const option = node("option", value); option.value = value; kind.append(option); }
    kind.value = original.kind ?? "banner";
    const dismissible = node("input"); dismissible.type = "checkbox"; dismissible.checked = original.dismissible === true;
    if (resource === "announcements") {
      const kindLabel = node("label", "Notice type"); kindLabel.append(kind);
      const dismissLabel = node("label", "Player may dismiss"); dismissLabel.append(dismissible);
      form.append(kindLabel, dismissLabel);
    }
    if (rules instanceof HTMLTextAreaElement) rules.rows = 14;
    if (resource === "events") form.append(node("p", "Gameplay publishing and private-room testing are not connected. Saving a draft does not affect runs."));
    const preview = node("article");
    const updatePreview = () => preview.replaceChildren(node("h3", name.value), node("p", description.value));
    name.oninput = updatePreview; description.oninput = updatePreview; updatePreview();
    const save = node("button", "Save"); save.type = "submit";
    const status = node("p"); status.setAttribute("role", "status");
    form.append(save, status, node("h3", "In-game content preview"), preview);
    let operationId = crypto.randomUUID();
    let pendingPayload: any;
    form.oninput = () => { operationId = crypto.randomUUID(); pendingPayload = null; };
    form.onsubmit = async event => {
      event.preventDefault();
      if (save.disabled) return;
      const controls = Array.from(form.querySelectorAll<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement | HTMLButtonElement>("input,select,textarea,button"));
      controls.forEach(control => { control.disabled = true; });
      status.textContent = "Saving…";
      try {
        const document = resource === "events"
          ? { ...original, ...JSON.parse(rules!.value), name: name.value, description: description.value, state: states.value }
          : { ...original, title: name.value, message: description.value, state: states.value, kind: kind.value, dismissible: dismissible.checked };
        document.startsAt = new Date(start.value).toISOString();
        document.endsAt = new Date(end.value).toISOString();
        pendingPayload ??= { id: record.id, version: record.version ?? 0, operationId, document };
        const result = await api(`/admin/live/${resource}`, pendingPayload);
        record.id = result.id; record.version = result.version;
        status.textContent = `Saved version ${result.version}.`;
        operationId = crypto.randomUUID(); pendingPayload = null;
      } catch (reason) { status.textContent = reason instanceof Error ? reason.message : String(reason); }
      finally { controls.forEach(control => { control.disabled = false; }); }
    };
    view.append(form);
  };
  const list = async (resource: Resource) => {
    const data = await api(`/admin/live/${resource}`);
    view.replaceChildren(node("h2", resource === "events" ? "Live Events" : "Announcements"));
    const create = node("button", "Create");
    const now = Date.now();
    create.onclick = () => edit(resource, { document: { name: "New event", title: "New notice", description: "", message: "", state: "draft", kind: "banner", dismissible: true, modes: [0], formats: ["solo"], rules: {}, startsAt: new Date(now).toISOString(), endsAt: new Date(now + 86400000).toISOString() } });
    view.append(create);
    if (resource === "events") {
      const templates = await api("/admin/live/templates");
      for (const draft of templates.drafts) {
        const button = node("button", `Create ${draft.name} draft`); button.onclick = () => edit(resource, { document: draft }); view.append(button);
      }
    }
    if (!data[resource].length) view.append(node("p", "Nothing saved yet."));
    for (const record of data[resource]) {
      const card = node("article");
      card.append(node("h3", record.document.name ?? record.document.title), node("p", `Version ${record.version} • ${record.status ?? record.document.state}`));
      const button = node("button", "Edit / preview"); button.onclick = () => edit(resource, record);
      const duplicate = node("button", "Duplicate draft"); duplicate.onclick = () => edit(resource, { document: { ...record.document, state: "draft" } });
      card.append(button, duplicate); view.append(card);
    }
  };
  for (const section of ["Dashboard", "Live Events", "Encounters & Drops", "Rooms & Runs", "Players & Rewards", "Announcements", "Audit Log"]) {
    const button = node("button", section); button.onclick = () => { void open(section); }; navigation.append(button);
  }
  await open("Dashboard");
}

export function removeMainNotices() { document.getElementById("live-main-notices")?.remove(); }
export async function showMainNotices() {
  removeMainNotices();
  const root = node("aside"); root.id = "live-main-notices";
  root.style.cssText = "position:fixed;top:8px;left:8px;max-width:45vw;max-height:28vh;overflow:auto;z-index:100;background:#303447;color:white;border:3px solid #b6312a;padding:8px;font:14px system-ui";
  root.hidden = true; document.body.append(root);
  try {
    const data = await api("/live/announcements");
    if (!root.isConnected) return;
    for (const announcement of data.announcements) {
      const key = `notice:${announcement.id}:${announcement.version}`;
      if (sessionStorage.getItem(key)) continue;
      const card = node("article"); card.append(node("strong", announcement.title), node("p", announcement.message));
      if (announcement.dismissible) {
        const dismiss = node("button", "Dismiss"); dismiss.onclick = () => { sessionStorage.setItem(key, "1"); card.remove(); if (!root.children.length) root.hidden = true; }; card.append(dismiss);
      }
      root.append(card);
    }
    root.hidden = !root.children.length;
  } catch { root.remove(); }
}
